use crate::aap::caps::http_client;
use crate::aap::caps::state_rw;
use crate::aap::caps::types::{FeedDocument, FetchFailure};

struct Node;

/// Escape a string as a JSON string literal (including the surrounding quotes).
fn json_string(s: &str) -> String {
    let mut out = String::with_capacity(s.len() + 2);
    out.push('"');
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            '\u{08}' => out.push_str("\\b"),
            '\u{0C}' => out.push_str("\\f"),
            c if (c as u32) < 0x20 => {
                let code = c as u32;
                const HEX: &[u8; 16] = b"0123456789abcdef";
                out.push_str("\\u00");
                out.push(HEX[((code >> 4) & 0xF) as usize] as char);
                out.push(HEX[(code & 0xF) as usize] as char);
            }
            c => out.push(c),
        }
    }
    out.push('"');
    out
}

/// Serialise the received subscription list as `{"urls":[...]}`.
fn encode_input(subscriptions: &SubscriptionList) -> String {
    let mut out = String::from("{\"urls\":[");
    for (i, url) in subscriptions.urls.iter().enumerate() {
        if i > 0 {
            out.push(',');
        }
        out.push_str(&json_string(url));
    }
    out.push_str("]}");
    out
}

impl Guest for Node {
    fn run(subscriptions: SubscriptionList) -> FeedBatch {
        // Record the input this call received in the shared store.
        state_rw::put("last-input", &encode_input(&subscriptions));

        let mut documents = Vec::new();
        let mut failures = Vec::new();

        for url in subscriptions.urls {
            match http_client::fetch(&url) {
                Ok(body) => documents.push(FeedDocument { url, body }),
                Err(error) => failures.push(FetchFailure { url, error }),
            }
        }

        FeedBatch {
            documents,
            failures,
        }
    }
}

export!(Node);
